            asm.GetManifestResourceNames()
            |> Array.filter (fun n -> n.EndsWith(".schema.json", StringComparison.OrdinalIgnoreCase))
            |> Array.map (fun name ->
                use stream = asm.GetManifestResourceStream(name)
                use reader = new StreamReader(stream)
                let schema = loadSchemaJson (reader.ReadToEnd())
                schema.TypeName, schema)
            |> Map.ofArray

