        | "boolean"
        | "integer"
        | "integer64"
        | "decimal"
        | "string"
        | "uri"
        | "url"
        | "canonical"
        | "base64Binary"
        | "instant"
        | "date"
        | "dateTime"
        | "time"
        | "code"
        | "oid"
        | "id"
        | "markdown"
        | "unsignedInt"
        | "positiveInt"
        | "uuid"
        | "xhtml" -> true
        | _ -> false

