    let private validateDate path (value: string) =
        if dateRegex.IsMatch value then
            if value.Length >= 7 then
                let monthPart = value.Substring(5, 2)

                match Int32.TryParse monthPart with
                | true, m when m < 1 || m > 12 -> [ fatal "Month should be in range [1; 12]." ]
                | true, _ when value.Length >= 10 ->
                    match DateTime.TryParseExact(value.Substring(0, 10), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None) with
                    | true, _ -> []
                    | false, _ -> [ fatal $"Invalid date '{value}' at {path}." ]
                | _ -> []
            else
                []
        else if value.Length >= 7 then
            let monthPart = value.Substring(5, 2)

            match Int32.TryParse monthPart with
            | true, m when m < 1 || m > 12 -> [ fatal "Month should be in range [1; 12]." ]
            | _ -> [ fatal $"Invalid date '{value}' at {path}." ]
        else
            [ fatal $"Invalid date '{value}' at {path}." ]

    let private validateRequiredBinding
        (valueSets: Map<string, Set<string>>)
        (_path: string)
        (valueSet: string)
