            if allowed.Contains c then
                []
            else
                [ fatal $"The provided code '#{code}' was not found in the value set '{valueSet}'" ]

    let private kindOk (typeName: string) (node: JsonNode) =
        let kind = node.GetValueKind()
        let t = normalizeTypeName typeName

        match t with
        | "boolean" -> kind = JsonValueKind.True || kind = JsonValueKind.False
        | "integer"
        | "positiveInt"
        | "unsignedInt"
        | "decimal" -> kind = JsonValueKind.Number
        // FHIR JSON: integer64 is a string
        | "integer64" -> kind = JsonValueKind.String
        | _ -> kind = JsonValueKind.String

    let private asString (node: JsonNode) =
        if node.GetValueKind() = JsonValueKind.String then
            node.GetValue<string>()
        else
            null

    let private checkPrimitiveFormat (path: string) (typeName: string) (node: JsonNode) =
        let t = normalizeTypeName typeName
        let s = asString node

        match t with
        | "date" when not (isNull s) -> validateDate path s
        | "dateTime" when not (isNull s) ->
            if dateTimeRegex.IsMatch s then []
            else [ fatal $"Invalid dateTime '{s}' at {path}." ]
        | "instant" when not (isNull s) ->
            if instantRegex.IsMatch s then []
            else [ fatal $"Invalid instant '{s}' at {path}." ]
        | "time" when not (isNull s) ->
            if timeRegex.IsMatch s then []
            else [ fatal $"Invalid time '{s}' at {path}." ]
        | "uri"
        | "url"
        | "canonical" when not (isNull s) ->
            if uriRegex.IsMatch s then []
            else [ fatal $"Invalid {t} '{s}' at {path}." ]
        | "oid" when not (isNull s) ->
            if oidRegex.IsMatch s then []
            else [ fatal $"Invalid oid '{s}' at {path}." ]
        | "uuid" when not (isNull s) ->
            if uuidRegex.IsMatch s then []
            else [ fatal $"Invalid uuid '{s}' at {path}." ]
        | "id" when not (isNull s) ->
            if idRegex.IsMatch s then []
            else [ fatal $"Invalid id '{s}' at {path}." ]
        | "base64Binary" when not (isNull s) ->
            if String.IsNullOrWhiteSpace s || base64Regex.IsMatch s then []
            else [ fatal $"Invalid base64Binary at {path}." ]
        | "positiveInt" when node.GetValueKind() = JsonValueKind.Number ->
            let n = node.GetValue<decimal>()
            if n >= 1m && Decimal.Truncate n = n then []
            else [ fatal $"{path}: positiveInt must be an integer >= 1." ]
        | "unsignedInt" when node.GetValueKind() = JsonValueKind.Number ->
            let n = node.GetValue<decimal>()
            if n >= 0m && Decimal.Truncate n = n then []
            else [ fatal $"{path}: unsignedInt must be an integer >= 0." ]
        | "integer" when node.GetValueKind() = JsonValueKind.Number ->
            let n = node.GetValue<decimal>()
            if Decimal.Truncate n = n then []
            else [ fatal $"{path}: integer must not have a fractional part." ]
        | "integer64" when not (isNull s) ->
            match Int64.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture) with
            | true, _ -> []
            | false, _ -> [ fatal $"Invalid integer64 '{s}' at {path}." ]
        | _ -> []

    let private checkPrimitive
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (typeName: string)
        (binding: ElementBinding option)
        (node: JsonNode)
        =
        if isNull node then
            [ fatal $"{path}: null is not allowed." ]
        elif not (kindOk typeName node) then
            [ fatal $"{path}: expected FHIR type '{normalizeTypeName typeName}'." ]
        else
            let s = asString node

            [
                yield! checkPrimitiveFormat path typeName node

                match binding with
                | Some b when b.Strength = "required" && not (isNull s) ->
                    yield! validateRequiredBinding valueSets path b.ValueSet s
                | _ -> ()
            ]

    let private emptyElements =
        Dictionary<string, ElementSchema>(StringComparer.Ordinal) :> IReadOnlyDictionary<string, ElementSchema>

    let private contentReferencePath (cref: string) =
        match cref.IndexOf('#') with
        | -1 -> cref.Trim()
        | i -> cref.Substring(i + 1).Trim()

    let private indexElementsByPath (root: ResourceSchema) =
        let dict = Dictionary<string, ElementSchema>(StringComparer.Ordinal)

        let rec walk (el: ElementSchema) =
            if not (String.IsNullOrEmpty el.Path) then
                dict[el.Path] <- el

            for KeyValue(_, child) in el.Elements do
                walk child

        for KeyValue(_, el) in root.Elements do
            walk el

        dict :> IReadOnlyDictionary<string, ElementSchema>

    let private resolveSchema
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (schema: ElementSchema)
        : ElementSchema =
        if schema.Elements.Count > 0 then
            schema
        else
            match schema.ContentReference with
            | Some cref ->
                let target = contentReferencePath cref

                match pathIndex.TryGetValue target with
                | true, referenced ->
                    { schema with
                        Types = if schema.Types = [] then referenced.Types else schema.Types
                        Binding = schema.Binding |> Option.orElse referenced.Binding
                        Elements = referenced.Elements }
                | _ -> schema
            | None ->
                schema.Types
                |> List.tryFind (fun t ->
                    let n = normalizeTypeName t
                    not (isPrimitive n) && Map.containsKey n schemas)
                |> Option.map (fun t ->
                    let dt = schemas[normalizeTypeName t]
                    { schema with Elements = dt.Elements })
                |> Option.defaultValue schema

    let private codingCodes (obj: JsonObject) =
        match tryProp obj "coding" with
        | Some(:? JsonArray as arr) ->
            [
                for i = 0 to arr.Count - 1 do
                    match arr[i] with
                    | :? JsonObject as coding ->
                        match tryProp coding "code" with
                        | Some n when n.GetValueKind() = JsonValueKind.String ->
                            yield n.GetValue<string>()
                        | _ -> ()
                    | _ -> ()
            ]
        | _ -> []

    /// Required binding on CodeableConcept: at least one coding.code must be in the value set (when known).
    let private validateCodeableConceptBinding
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (binding: ElementBinding option)
        (obj: JsonObject)
        =
        match binding with
        | Some b when b.Strength = "required" ->
            match valueSets |> Map.tryFind (canonicalValueSet b.ValueSet) with
            | None -> []
            | Some allowed when allowed.Count = 0 -> []
            | Some allowed ->
                let codes = codingCodes obj

                if codes = [] then
                    [ fatal $"{path}: required binding '{b.ValueSet}' needs a coding.code from the value set." ]
                elif codes |> List.exists allowed.Contains then
                    []
                else
                    let shown = codes |> List.tryHead |> Option.defaultValue ""
                    [ fatal $"The provided code '#{shown}' was not found in the value set '{b.ValueSet}'" ]
        | _ -> []

    let private validateCodingBinding
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (binding: ElementBinding option)
        (obj: JsonObject)
        =
        match binding with
        | Some b when b.Strength = "required" ->
            match tryProp obj "code" with
            | Some n when n.GetValueKind() = JsonValueKind.String ->
                validateRequiredBinding valueSets path b.ValueSet (n.GetValue<string>())
            | _ ->
                match valueSets |> Map.tryFind (canonicalValueSet b.ValueSet) with
                | Some s when s.Count > 0 ->
                    [ fatal $"{path}: required binding '{b.ValueSet}' needs a code." ]
                | _ -> []
        | _ -> []

    /// ele-1: All FHIR elements must have a @value or children (non-empty object).
    let private validateEle1 (path: string) (obj: JsonObject) =
        if obj.Count = 0 then
            [ fatal $"{path}: Element must have some content (ele-1)." ]
        else
            []

    /// meta.profile entries must be valid canonical URIs (full profile StructureDefinition checks are out of scope).
    let private validateMetaProfiles (path: string) (obj: JsonObject) =
        match tryProp obj "profile" with
        | Some(:? JsonArray as arr) ->
            [
                for i = 0 to arr.Count - 1 do
                    let item = arr[i]
                    let itemPath = $"{path}.profile[{i}]"

                    if isNull item || item.GetValueKind() <> JsonValueKind.String then
                        yield fatal $"{itemPath}: expected canonical string."
                    else
                        let s = item.GetValue<string>()

                        if String.IsNullOrWhiteSpace s || not (uriRegex.IsMatch s) then
                            yield fatal $"Invalid canonical '{s}' at {itemPath}."
                        elif not (s.StartsWith("http://", StringComparison.Ordinal)
                                  || s.StartsWith("https://", StringComparison.Ordinal)
                                  || s.StartsWith("urn:", StringComparison.Ordinal)) then
                            yield fatal $"{itemPath}: profile canonical should be an absolute URI."
            ]
        | Some _ -> [ fatal $"{path}.profile: expected array." ]
        | None -> []

    let rec private validateAgainst
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (schema: ElementSchema)
        (node: JsonNode)
        =
        if isNull node then
            if schema.Min >= 1 then
                [ fatal $"{path}: required element missing." ]
            else
                []
        elif schema.Array then
            match node with
            | :? JsonArray as arr ->
                let countIssues =
                    [
                        if arr.Count < schema.Min then
                            yield fatal $"{path}: expected at least {schema.Min} item(s), found {arr.Count}."

                        match schema.Max with
                        | Some max when arr.Count > max ->
                            yield fatal $"{path}: expected at most {max} item(s), found {arr.Count}."
                        | _ -> ()
                    ]

                let itemSchema = { schema with Array = false }

                let itemIssues =
                    [
                        for i = 0 to arr.Count - 1 do
                            let item = arr[i]
                            let itemPath = $"{path}[{i}]"

                            if isNull item then
                                yield fatal $"{itemPath}: null is not allowed."
                            else
                                yield! validateItem schemas pathIndex valueSets itemPath itemSchema item
                    ]

                countIssues @ itemIssues
            | _ -> [ fatal $"{path}: expected array." ]
        else
            validateItem schemas pathIndex valueSets path schema node

    and private validateChoice
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (schema: ElementSchema)
        (obj: JsonObject)
        =
        let present =
            schema.Choices
            |> List.choose (fun name -> tryProp obj name |> Option.map (fun n -> name, n))

        [
            if present = [] && schema.Min >= 1 then
                let choiceList = String.Join(", ", schema.Choices)
                yield fatal $"{path}: required choice missing (one of {choiceList})."

            match schema.Max, present with
            | Some 1, _ :: _ :: _ ->
                yield fatal $"{path}: only one choice allowed, found {present.Length}."
            | _ -> ()

            for name, node in present do
                let suffix =
                    if name.StartsWith(path, StringComparison.Ordinal) && name.Length > path.Length then
                        name.Substring(path.Length)
                    else
                        ""

                let typeHint =
                    if suffix = "" then
                        schema.Types |> List.tryHead |> Option.defaultValue ""
                    else
                        let t = string (Char.ToLowerInvariant suffix.[0]) + suffix.Substring(1)

                        if schema.Types |> List.exists (fun x -> x.Equals(t, StringComparison.OrdinalIgnoreCase)) then
                            t
                        else
                            schema.Types |> List.tryHead |> Option.defaultValue ""

                let childPath = $"{path}/{name}"

                if isPrimitive typeHint then
                    yield! checkPrimitive valueSets childPath typeHint schema.Binding node
                else
                    let choiceSchema =
                        { Path = childPath
                          Min = 0
                          Max = Some 1
                          Array = false
                          Types = [ typeHint ]
                          Binding = schema.Binding
                          Choices = []
                          ContentReference = None
                          Elements = emptyElements }
                        |> resolveSchema schemas pathIndex

                    match node with
                    | :? JsonObject
                    | :? JsonArray ->
                        yield! validateAgainst schemas pathIndex valueSets childPath choiceSchema node
                    | _ -> yield fatal $"{childPath}: expected complex type '{typeHint}'."
        ]

    and private validateItem
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (schema: ElementSchema)
        (node: JsonNode)
        =
        let prim =
            schema.Types
            |> List.map normalizeTypeName
            |> List.tryFind isPrimitive

        match prim with
        | Some t -> checkPrimitive valueSets path t schema.Binding node
        | None ->
            let resolved = resolveSchema schemas pathIndex schema

            match node with
            | :? JsonObject as obj ->
                let structural =
                    if resolved.Elements.Count > 0 then
                        validateObject schemas pathIndex valueSets path resolved obj
                    else
                        []

                let typeName =
                    resolved.Types
                    |> List.map normalizeTypeName
                    |> List.tryFind (fun t -> not (isPrimitive t))
                    |> Option.defaultValue ""

                let bindingIssues =
                    match typeName with
                    | "CodeableConcept" -> validateCodeableConceptBinding valueSets path schema.Binding obj
                    | "Coding" -> validateCodingBinding valueSets path schema.Binding obj
                    | "Meta" -> validateMetaProfiles path obj
                    | _ -> []

                let ele1 =
                    if resolved.Elements.Count > 0 || typeName <> "" then
                        validateEle1 path obj
                    else
                        []

                ele1 @ structural @ bindingIssues
            | _ ->
                let typeHint =
                    schema.Types
                    |> List.map normalizeTypeName
                    |> List.tryHead
                    |> Option.defaultValue "object"

                [ fatal $"{path}: expected object for type '{typeHint}'." ]

    and private validateObject
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (schema: ElementSchema)
        (obj: JsonObject)
        =
        [
            for KeyValue(name, child) in schema.Elements do
                let childPath = if path = "" then name else $"{path}.{name}"

                if child.Choices <> [] then
                    yield! validateChoice schemas pathIndex valueSets name child obj
                else
                    match tryProp obj name with
                    | Some childNode ->
                        yield! validateAgainst schemas pathIndex valueSets childPath child childNode
                    | None when child.Min >= 1 -> yield fatal $"{childPath}: required element missing."
                    | None -> ()
        ]

    let validate
        (schemas: Map<string, ResourceSchema>)
        (valueSets: Map<string, Set<string>>)
        (schema: ResourceSchema)
        (root: JsonObject)
        =
        let pathIndex = indexElementsByPath schema

        [
            match tryProp root "resourceType" with
            | Some n when n.GetValueKind() = JsonValueKind.String ->
                let rt = n.GetValue<string>()

                if rt <> schema.TypeName then
                    yield fatal $"resourceType '{rt}' does not match schema '{schema.TypeName}'."
            | _ -> yield fatal "resourceType is required."

            for name in schema.Required do
                match schema.Elements.TryGetValue name with
                | true, el when el.Choices <> [] -> () // enforced via validateChoice
                | _ when Option.isNone (tryProp root name) ->
                    yield fatal $"{name}: required element missing."
                | _ -> ()

            let rootSchema =
                { Path = schema.TypeName
                  Min = 0
                  Max = Some 1
                  Array = false
                  Types = []
                  Binding = None
                  Choices = []
                  ContentReference = None
                  Elements = schema.Elements }

            yield! validateObject schemas pathIndex valueSets "" rootSchema root
        ]

    let validateJson
        (schemas: Map<string, ResourceSchema>)
        (valueSets: Map<string, Set<string>>)
        (body: string)
        =
        if String.IsNullOrWhiteSpace body then
            [ fatal "Request body is required." ]
        else
            try
                match JsonNode.Parse(body) with
                | :? JsonObject as obj ->
                    match tryProp obj "resourceType" with
                    | Some n when n.GetValueKind() = JsonValueKind.String ->
                        let rt = n.GetValue<string>()

                        match Map.tryFind rt schemas with
                        | Some schema when schema.Kind = "complex-type" ->
                            [ fatal $"'{rt}' is a data type, not a resource." ]
                        | Some schema -> validate schemas valueSets schema obj
                        | None -> [ fatal $"No schema loaded for resourceType '{rt}'." ]
                    | _ -> [ fatal "resourceType is required." ]
                | _ -> [ fatal "Request body must be a JSON object." ]
            with ex ->
                [ fatal $"Unable to parse JSON: {ex.Message}" ]
